components.css:
.ds-btn-row { display: inline-flex; gap: 8px; align-items: center; }
.ds-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 8px 14px; border-radius: 8px; border: 1px solid transparent; font-family: 'Inter', system-ui, sans-serif; font-size: 13px; font-weight: 500; cursor: pointer; transition: background-color 140ms ease, border-color 140ms ease, transform 80ms ease; }
.ds-btn:active { transform: translateY(1px); }
.ds-btn:focus-visible { outline: 2px solid #5EEAD4; outline-offset: 2px; }
.ds-btn-primary { background: #5EEAD4; color: #071316; font-weight: 600; }
.ds-btn-primary:hover { background: #86F4E2; }
.ds-btn-outline { background: #121A2F; color: #F0F3FA; border-color: rgba(212, 175, 55, 0.34); font-family: 'JetBrains Mono', monospace; font-size: 12px; font-variant-numeric: tabular-nums; }
.ds-btn-outline:hover { background: #1A2440; }

.ds-patch-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 16px; border-radius: 12px; background: #0C1120; border: 1px solid rgba(212, 175, 55, 0.16); color: #F0F3FA; font-family: 'Inter', system-ui, sans-serif; }
.ds-patch-left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.ds-patch-meta { font-size: 13px; color: #B2BED6; }
.ds-mono { font-family: 'JetBrains Mono', monospace; font-size: 12px; font-variant-numeric: tabular-nums; color: #F0F3FA; }
.ds-badge { display: inline-flex; align-items: center; padding: 3px 9px; border-radius: 999px; font-family: 'JetBrains Mono', monospace; font-size: 11px; font-variant-numeric: tabular-nums; }
.ds-badge-gold { background: rgba(212, 175, 55, 0.14); border: 1px solid rgba(212, 175, 55, 0.36); color: #D4AF37; }

.ds-dual-wrap { display: flex; flex-direction: column; gap: 6px; padding: 12px 14px; border-radius: 12px; background: #0C1120; border: 1px solid rgba(212, 175, 55, 0.16); color: #F0F3FA; font-family: 'Inter', system-ui, sans-serif; font-size: 13px; }
.ds-dual-head { display: flex; justify-content: space-between; align-items: center; }
.ds-dual-nums { font-family: 'JetBrains Mono', monospace; font-size: 12px; font-variant-numeric: tabular-nums; color: #B2BED6; }
.ds-bar-dual { position: relative; height: 8px; border-radius: 999px; background: #121A2F; overflow: hidden; }
.ds-bar-func { position: absolute; inset: 0 auto 0 0; background: rgba(212, 175, 55, 0.48); border-radius: 999px; }
.ds-bar-max { position: absolute; inset: 0 auto 0 0; background: #34D399; border-radius: 999px; }

.ds-pills { display: inline-flex; flex-wrap: wrap; gap: 8px; }
.ds-pill { display: inline-flex; align-items: center; padding: 3px 9px; border-radius: 999px; font-family: 'JetBrains Mono', monospace; font-size: 11px; font-variant-numeric: tabular-nums; border: 1px solid transparent; }
.ds-pill-mint { background: rgba(52, 211, 153, 0.12); border-color: rgba(52, 211, 153, 0.36); color: #34D399; }
.ds-pill-gold { background: rgba(212, 175, 55, 0.14); border-color: rgba(212, 175, 55, 0.36); color: #D4AF37; }
.ds-pill-coral { background: rgba(248, 113, 113, 0.14); border-color: rgba(248, 113, 113, 0.36); color: #F87171; }

.ds-nav { display: inline-flex; gap: 4px; padding: 6px; border-radius: 12px; background: #0C1120; border: 1px solid rgba(212, 175, 55, 0.16); }
.ds-nav-item { background: transparent; border: 1px solid transparent; border-radius: 8px; padding: 6px 12px; color: #B2BED6; font-family: 'Inter', system-ui, sans-serif; font-size: 13px; font-weight: 500; cursor: pointer; transition: background-color 140ms ease, color 140ms ease; }
.ds-nav-item:hover { background: #1A2440; color: #F0F3FA; }
.ds-nav-item:focus-visible { outline: 2px solid #5EEAD4; outline-offset: 2px; }
.ds-nav-active { background: rgba(212, 175, 55, 0.14); border-color: rgba(212, 175, 55, 0.34); color: #F0F3FA; }
